sections.code:
/* Make base chat text, lists, and code blocks thicker */
.markdown p,
.markdown li,
.markdown td,
.query-text,
message-content,
.model-response-text {
    font-weight: 600 !important; /* Change to 600 if you want it semi-bold */
}

/* Keep actual bold text distinctly heavier so it still pops */
.markdown strong,
.markdown b,
.markdown h1,
.markdown h2,
.markdown h3,
.markdown th {
    font-weight: 800 !important;
}

/* Optional: Thicken up the code blocks too */
.markdown pre,
.markdown code {
    font-weight: 600 !important;
}

html{
    font-weight: 800 !important;
}
